// Parse incoming denial data from DrChrono ERA/835 webhook or manual entry
const input = $input.first().json;

// Determine input format
let inputData;
let source;

if (input.era_835) {
  // ERA/835 electronic remittance from DrChrono
  inputData = input.era_835;
  source = 'drchrono_era';
} else if (input.manual_entry) {
  // Manual entry from billing staff
  inputData = input.manual_entry;
  source = 'manual';
} else {
  // Raw body — treat as unstructured text
  inputData = JSON.stringify(input);
  source = 'raw';
}

// If structured data has required fields, skip Gemini classification
let needsClassification = true;
let parsedData = {};

if (input.denial_code && input.patient_name && input.dos && input.denied_amount) {
  needsClassification = false;
  parsedData = {
    denial_code: input.denial_code,
    denial_label: {
      'PTOT08A': 'MTB Reached',
      'PTOT05': 'Non-Skilled',
      'PTOT21': 'Re-eval Bundled',
      'PTOT19': 'Dup Eval'
    }[input.denial_code] || 'Unknown',
    patient_name: input.patient_name,
    member_id: input.member_id || '',
    dos: input.dos,
    denied_amount: parseFloat(input.denied_amount) || 0,
    denial_date: input.denial_date || new Date().toISOString().split('T')[0],
    plan_type: input.plan_type || 'Unknown',
    claim_number: input.claim_number || '',
    provider: input.provider || '',
    location: input.location || '',
    cpt_codes: input.cpt_codes || [],
    npi: input.npi || ''
  };
}

return [{
  json: {
    source,
    needs_classification: needsClassification,
    raw_input: inputData,
    parsed_data: parsedData
  }
}];

// Parse Gemini classification response
const response = $input.first().json;
let text = '';

if (response.candidates && response.candidates[0]) {
  const parts = response.candidates[0].content?.parts || [];
  text = parts.map(p => p.text || '').join('');
}

// Strip markdown code fences
text = text.trim();
if (text.startsWith('```')) text = text.split('\n').slice(1).join('\n');
if (text.endsWith('```')) text = text.slice(0, text.lastIndexOf('```'));
text = text.trim();
if (text.startsWith('json')) text = text.slice(4).trim();

let classification;
try {
  classification = JSON.parse(text);
} catch (e) {
  throw new Error(`Failed to parse Gemini response as JSON: ${e.message}. Raw: ${text.slice(0, 200)}`);
}

const c = classification.classification || {};
const patient = classification.patient || {};
const claim = classification.claim || {};
const payer = classification.payer || {};
const provider = classification.provider || {};

// Calculate filing deadline: denial_date + 365 days
const denialDate = claim.denial_date || new Date().toISOString().split('T')[0];
const deadline = new Date(denialDate);
deadline.setDate(deadline.getDate() + 365);

return [{
  json: {
    denial_code: c.denial_code || 'UNKNOWN',
    denial_label: c.denial_label || 'Unknown',
    confidence: c.confidence || 0,
    reasoning: c.reasoning || '',
    patient_name: patient.name || 'Unknown Patient',
    member_id: patient.member_id || '',
    dos: claim.dos_start || '',
    denied_amount: parseFloat(claim.denied_amount) || 0,
    denial_date: denialDate,
    filing_deadline: deadline.toISOString().split('T')[0],
    plan_type: payer.plan_type || 'Unknown',
    claim_number: claim.claim_number || '',
    provider: provider.name || '',
    npi: provider.npi || '',
    cpt_codes: claim.cpt_codes || [],
    location: '',
    missing_fields: classification.missing_fields || [],
    urgency: classification.urgency || 'standard',
    source: 'gemini_classified'
  }
}];

// Pass through pre-parsed structured data (no AI needed)
const data = $input.first().json.parsed_data;

// Calculate filing deadline if not present
if (!data.filing_deadline) {
  const denialDate = data.denial_date || new Date().toISOString().split('T')[0];
  const deadline = new Date(denialDate);
  deadline.setDate(deadline.getDate() + 365);
  data.filing_deadline = deadline.toISOString().split('T')[0];
}

// Determine urgency
const today = new Date();
const deadlineDate = new Date(data.filing_deadline);
const daysRemaining = Math.ceil((deadlineDate - today) / (1000 * 60 * 60 * 24));
data.urgency = daysRemaining < 30 ? 'urgent' : 'standard';
data.source = 'structured_input';

return [{ json: data }];

// Merge both paths into a single normalized item for Monday.com
const data = $input.first().json;

// Build Monday.com column values JSON
const columnValues = {
  // Denial Code (dropdown)
  dropdown_mm0ffjcd: {
    labels: [`${data.denial_code} - ${data.denial_label}`]
  },
  // DOS (date)
  date_mm0fp9n1: {
    date: data.dos || ''
  },
  // Amount (numbers)
  numeric_mm0fh3jn: String(data.denied_amount || 0),
  // Plan Type (dropdown)
  dropdown_mm0fjy49: {
    labels: [data.plan_type || 'Unknown']
  },
  // Denial Date
  date_mm0frn70: {
    date: data.denial_date || ''
  },
  // Filing Deadline
  date_mm0fgzne: {
    date: data.filing_deadline || ''
  },
  // Appeal Status (status) — set to New
  color_mm0fj7fm: {
    label: 'New'
  },
  // Provider (dropdown)
  dropdown_mm0fdaya: data.provider ? { labels: [data.provider] } : {},
  // Location (dropdown)
  dropdown_mm0fac7b: data.location ? { labels: [data.location] } : {}
};

return [{
  json: {
    item_name: `${data.patient_name} — ${data.denial_code}`,
    column_values: JSON.stringify(columnValues),
    group_id: 'group_mm0fc0ne',  // New Denials
    ...data
  }
}];

// Extract Monday.com item ID and prepare alert message
const response = $input.first().json;
const item = response?.data?.create_item;

if (!item || !item.id) {
  throw new Error('Failed to create Monday.com item: ' + JSON.stringify(response));
}

// Get original data from earlier in the pipeline
const data = $('Build Monday.com Item').first().json;

const urgencyLabel = data.urgency === 'urgent' ? ' [URGENT]' : '';
const alertMessage = `New Denial Received${urgencyLabel}\n` +
  `Patient: ${data.patient_name}\n` +
  `Code: ${data.denial_code} — ${data.denial_label}\n` +
  `Amount: $${data.denied_amount}\n` +
  `DOS: ${data.dos}\n` +
  `Filing Deadline: ${data.filing_deadline}\n` +
  `Board: https://phw-team.monday.com/boards/18399605169`;

return [{
  json: {
    monday_item_id: item.id,
    monday_item_name: item.name,
    alert_message: alertMessage,
    ...data
  }
}];

// Final response with success status
const data = $('Prepare Alert').first().json;

return [{
  json: {
    status: 'success',
    message: `Denial intake processed for ${data.patient_name}`,
    monday_item_id: data.monday_item_id,
    denial_code: data.denial_code,
    filing_deadline: data.filing_deadline
  }
}];
